hd_.APR_computeCI_NoNuis <- function (betahat, sigma, A, d, numPrePeriods, numPostPeriods, l_vec, alpha, returnLength, hybrid_flag, 
    hybrid_list, grid.ub, grid.lb, gridPoints, postPeriodMomentsOnly) 
{
    thetaGrid <- base::seq(grid.lb, grid.ub, length.out = gridPoints)
    if (hybrid_flag == "ARP") {
        resultsGrid <- hd_.testOverThetaGrid(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
            A = A, d = d, thetaGrid = thetaGrid, alpha = alpha)
    }
    else if (hybrid_flag == "FLCI") {
        resultsGrid <- hd_.testOverThetaGrid(betahat = betahat, sigma = sigma, thetaGrid = thetaGrid, A = A, 
            d = d, alpha = alpha, numPrePeriods = numPrePeriods, testFn = hd_.testInIdentifiedSet_FLCI_Hybrid, 
            hybrid_list = hybrid_list)
    }
    else if (hybrid_flag == "LF") {
        resultsGrid <- hd_.testOverThetaGrid(betahat = betahat, sigma = sigma, thetaGrid = thetaGrid, A = A, 
            d = d, alpha = alpha, numPrePeriods = numPrePeriods, testFn = hd_.testInIdentifiedSet_LF_Hybrid, 
            hybrid_list = hybrid_list)
    }
    else {
        base::stop("hybrid_flag must equal 'APR' or 'FLCI' or 'LF'")
    }
    if (resultsGrid[1] == 1 | resultsGrid[base::length(resultsGrid)] == 1) {
        base::warning("CI is open at one of the endpoints; CI length may not be accurate")
    }
    if (returnLength == TRUE) {
        gridLength <- 0.5 * (base::c(0, base::diff(thetaGrid)) + base::c(base::diff(thetaGrid), 0))
        base::return(base::sum(resultsGrid[, 2] * gridLength))
    }
    else {
        base::return(tibble::tibble(grid = resultsGrid[, 1], accept = resultsGrid[, 2]))
    }
}

hd_.ARP_computeCI <- function (betahat, sigma, numPrePeriods, numPostPeriods, A, d, l_vec, alpha, hybrid_flag, hybrid_list, 
    returnLength, grid.lb, grid.ub, gridPoints, rowsForARP = NULL) 
{
    thetaGrid <- base::seq(grid.lb, grid.ub, length.out = gridPoints)
    Gamma = hd_.construct_Gamma(l_vec)
    AGammaInv = A[, (numPrePeriods + 1):(numPrePeriods + numPostPeriods)] %*% base::solve(Gamma)
    AGammaInv_one = AGammaInv[, 1]
    AGammaInv_minusOne = AGammaInv[, -1]
    Y = base::c(A %*% betahat - d)
    sigmaY = A %*% sigma %*% base::t(A)
    if (hybrid_flag == "LF") {
        hybrid_list$lf_cv = hd_.compute_least_favorable_cv(X_T = AGammaInv_minusOne, sigma = sigmaY, hybrid_kappa = hybrid_list$hybrid_kappa, 
            rowsForARP = rowsForARP)
    }
    testTheta <- function(theta) {
        if (hybrid_flag == "FLCI") {
            hybrid_list$dbar = base::c(hybrid_list$flci_halflength - (t(hybrid_list$vbar) %*% d) + (1 - 
                t(hybrid_list$vbar) %*% AGammaInv_one) * theta, hybrid_list$flci_halflength + (t(hybrid_list$vbar) %*% 
                d) - (1 - t(hybrid_list$vbar) %*% AGammaInv_one) * theta)
        }
        reject = hd_.test_delta_lp_fn_wrapper(theta = theta, y_T = Y - AGammaInv_one * theta, X_T = AGammaInv_minusOne, 
            sigma = sigmaY, alpha = alpha, hybrid_flag = hybrid_flag, hybrid_list = hybrid_list, rowsForARP = rowsForARP)
        accept = 1 - reject
        base::return(accept)
    }
    testResultsGrid <- purrr::map_dbl(.x = thetaGrid, .f = testTheta)
    testValsGrid <- thetaGrid
    resultsGrid <- base::cbind(testValsGrid, testResultsGrid)
    if ((resultsGrid[1, 2] == 1 | resultsGrid[base::NROW(resultsGrid), 2] == 1) & hybrid_flag != "FLCI") {
        base::warning("CI is open at one of the endpoints; CI length may not be accurate")
    }
    if (returnLength == TRUE) {
        gridLength <- 0.5 * (base::c(0, base::diff(thetaGrid)) + base::c(base::diff(thetaGrid), 0))
        base::return(base::sum(resultsGrid[, 2] * gridLength))
    }
    else {
        base::return(tibble::tibble(grid = resultsGrid[, 1], accept = resultsGrid[, 2]))
    }
}

hd_.check_if_solution_helper <- function (c, tol, s_T, gamma_tilde, sigma, W_T) 
{
    linprog = hd_.max_program(s_T, gamma_tilde, sigma, W_T, c)
    linprog$honestsolution = (base::abs(c - (-linprog$optimum)) <= tol)
    base::return(linprog)
}

hd_.compute_least_favorable_cv <- function (X_T, sigma, hybrid_kappa, sims = 1000, rowsForARP = NULL, seed = 0) 
{
    if (!base::is.null(rowsForARP)) {
        if (base::is.vector(X_T)) {
            X_T = base::matrix(X_T[rowsForARP], ncol = 1)
        }
        else {
            X_T <- X_T[rowsForARP, ]
        }
        sigma <- sigma[rowsForARP, rowsForARP]
    }
    .compute_eta <- function(b, f, C) {
        linprog = lpSolveAPI::make.lp(nrow = 0, ncol = base::length(f))
        lpSolveAPI::set.objfn(linprog, f)
        for (r in 1:base::dim(C)[1]) {
            lpSolveAPI::add.constraint(linprog, xt = base::c(C[r, ]), type = "<=", rhs = b[r])
        }
        lpSolveAPI::set.bounds(linprog, lower = base::rep(-Inf, base::length(f)), columns = 1:base::length(f))
        lpSolveAPI::lp.control(linprog, sense = "min", simplextype = "dual", pivoting = "dantzig", verbose = "neutral", 
            timeout = 10)
        error_flag = lpSolveAPI::solve.lpExtPtr(linprog)
        base::return(if (error_flag) 
            NA
        else lpSolveAPI::get.objective(linprog))
    }
    base::set.seed(seed)
    if (base::is.null(X_T)) {
        xi.draws = t(t(mvtnorm::rmvnorm(n = sims, sigma = sigma))/base::sqrt(base::diag(sigma)))
        eta_vec = matrixStats::rowMaxs(xi.draws)
        base::return(stats::quantile(eta_vec, probs = 1 - hybrid_kappa, names = FALSE))
    }
    else {
        sdVec = base::sqrt(base::diag(sigma))
        dimDelta = base::dim(X_T)[2]
        f = base::c(1, base::rep(0, dimDelta))
        C = -base::cbind(sdVec, X_T)
        xi.draws = mvtnorm::rmvnorm(n = sims, sigma = sigma)
        eta_vec = base::apply(-xi.draws, 1, .compute_eta, f, C)
        base::return(stats::quantile(eta_vec, probs = 1 - hybrid_kappa, names = FALSE, na.rm = TRUE))
    }
}

hd_.computeConditionalCS_DeltaRM_fixedS <- function (s, max_positive, Mbar, betahat, sigma, numPrePeriods, numPostPeriods, l_vec, alpha, hybrid_flag, 
    hybrid_kappa, postPeriodMomentsOnly, gridPoints, grid.ub, grid.lb, seed = 0) 
{
    if (hybrid_flag != "LF" & hybrid_flag != "ARP") {
        base::stop("hybrid_flag must equal 'ARP' or 'LF'")
    }
    hybrid_list = base::list(hybrid_kappa = hybrid_kappa)
    A_RM_s = hd_.create_A_RM(numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods, Mbar = Mbar, 
        s = s, max_positive = max_positive)
    d_RM = hd_.create_d_RM(numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods)
    if (postPeriodMomentsOnly) {
        if (numPostPeriods > 1) {
            postPeriodIndices <- (numPrePeriods + 1):base::NCOL(A_RM_s)
            postPeriodRows <- base::which(base::rowSums(A_RM_s[, postPeriodIndices] != 0) > 0)
            rowsForARP <- postPeriodRows
        }
        else {
            postPeriodRows <- base::which(A_RM_s[, NCOL(A_RM_s)] != 0)
            A_RM_s <- A_RM_s[postPeriodRows, ]
            d_RM <- d_RM[postPeriodRows]
        }
    }
    else {
        rowsForARP <- 1:base::NROW(A_RM_s)
    }
    if (numPostPeriods == 1) {
        if (hybrid_flag == "LF") {
            lf_cv = hd_.compute_least_favorable_cv(X_T = NULL, sigma = A_RM_s %*% sigma %*% base::t(A_RM_s), 
                hybrid_kappa = hybrid_kappa, seed = seed)
            hybrid_list$lf_cv = lf_cv
        }
        CI <- hd_.APR_computeCI_NoNuis(betahat = betahat, sigma = sigma, A = A_RM_s, d = d_RM, numPrePeriods = numPrePeriods, 
            numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, returnLength = FALSE, hybrid_flag = hybrid_flag, 
            hybrid_list = hybrid_list, grid.ub = grid.ub, grid.lb = grid.lb, gridPoints = gridPoints)
    }
    else {
        CI = hd_.ARP_computeCI(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods, 
            A = A_RM_s, d = d_RM, l_vec = l_vec, alpha = alpha, hybrid_flag = hybrid_flag, hybrid_list = hybrid_list, 
            returnLength = FALSE, grid.lb = grid.lb, grid.ub = grid.ub, gridPoints = gridPoints, rowsForARP = rowsForARP)
    }
    base::return(CI)
}

