hd_.construct_Gamma <- function (l) 
{
    barT = base::length(l)
    B = base::cbind(l, base::diag(barT))
    rrefB = pracma::rref(B)
    leading_ones <- purrr::map_dbl(.x = 1:base::dim(rrefB)[1], hd_.leading_one, B = rrefB)
    Gamma = base::t(B[, leading_ones])
    if (base::det(Gamma) == 0) {
        base::stop("Something went wrong in RREF algorithm.")
    }
    else {
        base::return(Gamma)
    }
}

hd_.create_A_B <- function (numPrePeriods, numPostPeriods, biasDirection) 
{
    A_B = -base::diag(numPrePeriods + numPostPeriods)
    A_B = A_B[(numPrePeriods + 1):(numPrePeriods + numPostPeriods), ]
    if (biasDirection == "negative") {
        A_B <- -A_B
    }
    else if (biasDirection != "positive") {
        base::stop("Input biasDirection must equal either `positive' or `negative'")
    }
    base::return(A_B)
}

hd_.create_A_M <- function (numPrePeriods, numPostPeriods, monotonicityDirection, postPeriodMomentsOnly) 
{
    A_M = base::matrix(0, nrow = numPrePeriods + numPostPeriods, ncol = numPrePeriods + numPostPeriods)
    for (r in 1:(numPrePeriods - 1)) {
        A_M[r, r:(r + 1)] <- base::c(1, -1)
    }
    A_M[numPrePeriods, numPrePeriods] <- 1
    if (numPostPeriods > 0) {
        A_M[numPrePeriods + 1, numPrePeriods + 1] <- -1
        if (numPostPeriods > 1) {
            for (r in (numPrePeriods + 2):(numPrePeriods + numPostPeriods)) {
                A_M[r, (r - 1):r] <- c(1, -1)
            }
        }
    }
    if (postPeriodMomentsOnly) {
        postPeriodIndices <- (numPrePeriods + 1):base::NCOL(A_M)
        prePeriodOnlyRows <- base::which(base::rowSums(A_M[, postPeriodIndices] != 0) == 0)
        A_M <- A_M[-prePeriodOnlyRows, ]
    }
    if (monotonicityDirection == "decreasing") {
        A_M <- -A_M
    }
    else if (monotonicityDirection != "increasing") {
        base::stop("direction must be 'increasing' or 'decreasing'")
    }
    base::return(A_M)
}

hd_.create_A_RM <- function (numPrePeriods, numPostPeriods, Mbar = 1, s, max_positive = TRUE, dropZero = TRUE) 
{
    Atilde = base::matrix(0, nrow = numPrePeriods + numPostPeriods, ncol = numPrePeriods + numPostPeriods + 
        1)
    for (r in 1:(numPrePeriods + numPostPeriods)) {
        Atilde[r, r:(r + 1)] = c(-1, 1)
    }
    v_max_dif <- base::matrix(0, nrow = 1, ncol = numPrePeriods + numPostPeriods + 1)
    v_max_dif[(numPrePeriods + s):(numPrePeriods + 1 + s)] <- c(-1, 1)
    if (max_positive == FALSE) {
        v_max_dif <- -v_max_dif
    }
    A_UB <- base::rbind(pracma::repmat(v_max_dif, n = numPrePeriods, m = 1), pracma::repmat(Mbar * v_max_dif, 
        n = numPostPeriods, m = 1))
    A = base::rbind(Atilde - A_UB, -Atilde - A_UB)
    zerorows <- base::apply(X = A, MARGIN = 1, FUN = function(x) t(x) %*% x) <= 10^-10
    A <- A[!zerorows, ]
    if (dropZero) {
        A = A[, -(numPrePeriods + 1)]
        base::return(A)
    }
    else {
        base::return(A)
    }
}

