hd_.CustomErrorHandling <- function (code, custom) 
{
    base::tryCatch({
        code
    }, error = function(e) {
        base::message(custom)
        base::message("\tcall:  ", base::paste0(rlang::expr_deparse(e$call), collapse = "\n\t"))
        base::message("\terror: ", e$message)
        base::message("Traceback:")
        traceback()
        base::stop(e)
    })
}

hd_.FLCI_computeVloVup <- function (vbar, dbar, S, c) 
{
    VbarMat = base::rbind(t(vbar), -t(vbar))
    max_or_min = (dbar - (VbarMat %*% S))/(VbarMat %*% c)
    vlo = base::max(max_or_min[VbarMat %*% c < 0])
    vup = base::min(max_or_min[VbarMat %*% c > 0])
    base::return(base::list(vlo = vlo, vup = vup))
}

hd_.leading_one <- function (r, B) 
{
    i = 1
    while (B[r, i] == 0) {
        i = i + 1
    }
    base::return(i)
}

hd_.LeeCFN <- function (eta, Sigma) 
{
    c = Sigma %*% eta/base::as.numeric(base::t(eta) %*% Sigma %*% eta)
    base::return(c)
}

hd_.lp_conditional_test_fn <- function (theta, y_T, X_T, sigma, alpha, hybrid_flag, hybrid_list, rowsForARP = 1:base::length(y_T)) 
{
    y_T_ARP <- y_T[rowsForARP]
    if (base::is.vector(X_T)) {
        X_T = base::matrix(X_T, ncol = 1)
    }
    X_T_ARP <- X_T[rowsForARP, ]
    if (base::is.vector(X_T_ARP)) {
        X_T_ARP = base::matrix(X_T_ARP, ncol = 1)
    }
    sigma_ARP <- sigma[rowsForARP, rowsForARP]
    M = base::dim(sigma_ARP)[1]
    k = base::dim(X_T_ARP)[2]
    linSoln = hd_.test_delta_lp_fn(y_T = y_T_ARP, X_T = X_T_ARP, sigma = sigma_ARP)
    if (linSoln$error_flag > 0) {
        base::warning("LP for eta did not converge properly. Not rejecting")
        base::return(base::list(reject = 0, eta = linSoln$eta_star, delta = linSoln$delta_star))
    }
    if (hybrid_flag == "LF") {
        mod_size = (alpha - hybrid_list$hybrid_kappa)/(1 - hybrid_list$hybrid_kappa)
        if (linSoln$eta_star > hybrid_list$lf_cv) {
            base::return(base::list(reject = 1, eta = linSoln$eta_star, delta = linSoln$delta_star))
        }
    }
    else if (hybrid_flag == "FLCI") {
        mod_size = (alpha - hybrid_list$hybrid_kappa)/(1 - hybrid_list$hybrid_kappa)
        VbarMat = base::rbind(base::t(hybrid_list$vbar), -t(hybrid_list$vbar))
        if ((base::max(VbarMat %*% y_T - hybrid_list$dbar)) > 0) {
            base::return(base::list(reject = 1, eta = linSoln$eta_star, delta = linSoln$delta_star))
        }
    }
    else if (hybrid_flag == "ARP") {
        mod_size = alpha
    }
    else {
        base::stop("Hybrid flag must equal 'LF', 'FLCI' or 'ARP'")
    }
    tol_lambda = 10^(-6)
    degenerate_flag = (base::sum(linSoln$lambda > tol_lambda) != (k + 1))
    B_index = (linSoln$lambda > tol_lambda)
    Bc_index = (B_index == FALSE)
    X_TB = base::matrix(X_T_ARP[B_index, ], ncol = base::ncol(X_T_ARP))
    Xdim = base::min(base::dim(X_TB))
    if (base::is.vector(X_TB) | (Xdim == 0)) {
        fullRank_flag = FALSE
    }
    else {
        fullRank_flag = (Matrix::rankMatrix(X_TB) == Xdim)
    }
    if (!fullRank_flag | degenerate_flag) {
        lpDualSoln = hd_.lp_dual_fn(y_T = y_T_ARP, X_T = X_T_ARP, eta = linSoln$eta_star, gamma_tilde = linSoln$lambda, 
            sigma = sigma_ARP)
        sigma_B_dual2 = base::t(lpDualSoln$gamma_tilde) %*% sigma_ARP %*% lpDualSoln$gamma_tilde
        if (base::abs(sigma_B_dual2) < .Machine$double.eps) {
            base::return(base::list(reject = base::ifelse(linSoln$eta_star > 0, 1, 0), eta = linSoln$eta_star, 
                delta = linSoln$delta_star, lambda = linSoln$lambda))
        }
        else if (sigma_B_dual2 < 0) {
            base::stop("hd_.vlo_vup_dual_fn returned a negative variance")
        }
        sigma_B_dual = base::sqrt(sigma_B_dual2)
        maxstat = lpDualSoln$eta/sigma_B_dual
        if (hybrid_flag == "LF") {
            zlo_dual = lpDualSoln$vlo/sigma_B_dual
            zup_dual = base::min(lpDualSoln$vup, hybrid_list$lf_cv)/sigma_B_dual
        }
        else if (hybrid_flag == "FLCI") {
            gamma_full <- base::matrix(0, nrow = base::length(y_T), ncol = 1)
            gamma_full[rowsForARP] <- lpDualSoln$gamma_tilde
            sigma_gamma = (sigma %*% gamma_full) %*% base::solve((base::t(gamma_full) %*% sigma %*% gamma_full))
            S = y_T - sigma_gamma %*% (base::t(gamma_full) %*% y_T)
            vFLCI = hd_.FLCI_computeVloVup(vbar = hybrid_list$vbar, dbar = hybrid_list$dbar, S = S, c = sigma_gamma)
            zlo_dual = base::max(lpDualSoln$vlo, vFLCI$vlo)/sigma_B_dual
            zup_dual = base::min(lpDualSoln$vup, vFLCI$vup)/sigma_B_dual
        }
        else if (hybrid_flag == "ARP") {
            zlo_dual = lpDualSoln$vlo/sigma_B_dual
            zup_dual = lpDualSoln$vup/sigma_B_dual
        }
        else {
            base::stop("Hybrid flag must equal 'LF', 'FLCI' or 'ARP'")
        }
        if (!(zlo_dual <= maxstat & maxstat <= zup_dual)) {
            base::return(base::list(reject = 0, eta = linSoln$eta_star, delta = linSoln$delta_star, lambda = linSoln$lambda))
        }
        else {
            cval = base::max(0, hd_.norminvp_generalized(p = 1 - mod_size, l = zlo_dual, u = zup_dual))
            reject = base::as.numeric(c(maxstat) > cval)
            base::return(base::list(reject = reject, eta = linSoln$eta_star, delta = linSoln$delta_star, 
                lambda = linSoln$lambda))
        }
    }
    else {
        size_B = base::sum(B_index)
        size_Bc = base::sum(1 - B_index)
        sdVec = base::sqrt(base::diag(sigma_ARP))
        sdVec_B = sdVec[B_index]
        sdVec_Bc = sdVec[Bc_index]
        X_TBc = X_T_ARP[Bc_index, ]
        S_B = base::diag(M)
        S_B = S_B[B_index, ]
        S_Bc = base::diag(M)
        S_Bc = S_Bc[Bc_index, ]
        Gamma_B = base::cbind(sdVec_Bc, X_TBc) %*% base::solve(base::cbind(sdVec_B, X_TB)) %*% S_B - 
            S_Bc
        e1 = base::c(1, base::rep(0, size_B - 1))
        v_B = base::t(base::t(e1) %*% base::solve(base::cbind(sdVec_B, X_TB)) %*% S_B)
        sigma2_B = base::t(v_B) %*% sigma_ARP %*% v_B
        sigma_B = base::sqrt(sigma2_B)
        rho = Gamma_B %*% sigma_ARP %*% v_B %*% base::solve(sigma2_B)
        maximand_or_minimand = (-Gamma_B %*% y_T_ARP)/rho + base::c(base::t(v_B) %*% y_T_ARP)
        if (base::sum(rho > 0) > 0) {
            vlo = base::max(maximand_or_minimand[rho > 0])
        }
        else {
            vlo = -Inf
        }
        if (base::sum(rho < 0) > 0) {
            vup = base::min(maximand_or_minimand[rho < 0])
        }
        else {
            vup = Inf
        }
        if (hybrid_flag == "LF") {
            zlo = vlo/sigma_B
            zup = base::min(vup, hybrid_list$lf_cv)/sigma_B
        }
        else if (hybrid_flag == "FLCI") {
            gamma_full <- base::matrix(0, nrow = base::length(y_T), ncol = 1)
            gamma_full[rowsForARP] <- v_B
            sigma_gamma = (sigma %*% gamma_full) %*% base::solve((base::t(gamma_full) %*% sigma %*% gamma_full))
            S = y_T - sigma_gamma %*% (base::t(gamma_full) %*% y_T)
            vFLCI = hd_.FLCI_computeVloVup(vbar = hybrid_list$vbar, dbar = hybrid_list$dbar, S = S, c = sigma_gamma)
            zlo = base::max(vlo, vFLCI$vlo)/sigma_B
            zup = base::min(vup, vFLCI$vup)/sigma_B
        }
        else if (hybrid_flag == "ARP") {
            zlo = vlo/sigma_B
            zup = vup/sigma_B
        }
        else {
            base::stop("Hybrid flag must equal 'LF', 'FLCI' or 'ARP'")
        }
        maxstat = linSoln$eta_star/sigma_B
        if (!(zlo <= maxstat & maxstat <= zup)) {
            base::return(base::list(reject = 0, eta = linSoln$eta_star, delta = linSoln$delta_star, lambda = linSoln$lambda))
        }
        else {
            cval = base::max(0, hd_.norminvp_generalized(p = 1 - mod_size, l = zlo, u = zup))
            reject = base::as.numeric(c(maxstat) > cval)
            base::return(base::list(reject = reject, eta = linSoln$eta_star, delta = linSoln$delta_star, 
                lambda = linSoln$lambda))
        }
    }
}

hd_.lp_dual_fn <- function (y_T, X_T, eta, gamma_tilde, sigma) 
{
    sdVec = base::sqrt(base::diag(sigma))
    W_T = base::cbind(sdVec, X_T)
    s_T = (base::diag(base::length(y_T)) - base::c(base::t(gamma_tilde) %*% sigma %*% gamma_tilde)^(-1) * 
        (sigma %*% (gamma_tilde %*% base::t(gamma_tilde)))) %*% y_T
    vList = hd_.vlo_vup_dual_fn(eta = eta, s_T = s_T, gamma_tilde = gamma_tilde, sigma = sigma, W_T = W_T)
    base::return(base::list(vlo = vList$vlo, vup = vList$vup, eta = eta, gamma_tilde = gamma_tilde))
}

hd_.max_program <- function (s_T, gamma_tilde, sigma, W_T, c) 
{
    f = s_T + base::c(base::t(gamma_tilde) %*% sigma %*% gamma_tilde)^(-1) * (sigma %*% gamma_tilde) * 
        c
    Aeq = base::t(W_T)
    beq = base::c(1, base::rep(0, base::dim(Aeq)[1] - 1))
    linprog = Rglpk::Rglpk_solve_LP(obj = -base::c(f), mat = Aeq, dir = base::rep("==", base::NROW(Aeq)), 
        rhs = beq)
    base::return(linprog)
}

hd_.norminvp_generalized <- function (p, l, u, mu = 0, sd = 1) 
{
    lnormalized <- (l - mu)/sd
    unormalized <- (u - mu)/sd
    qnormalized <- TruncatedNormal::norminvp(p, lnormalized, unormalized)
    q <- mu + qnormalized * sd
    base::return(q)
}

hd_.roundeps <- function (x, eps = .Machine$double.eps^(3/4)) 
{
    if (base::abs(x) < eps) 
        base::return(0)
    else base::return(x)
}

hd_.selectionMat <- function (selection, size, select = "columns") 
{
    if (select == "rows") {
        m <- base::matrix(0, nrow = base::length(selection), ncol = size)
        m[1:base::length(selection), selection] <- base::diag(base::length(selection))
    }
    else {
        m <- base::matrix(0, ncol = base::length(selection), nrow = size)
        m[selection, 1:base::length(selection)] <- base::diag(base::length(selection))
    }
    base::return(m)
}

hd_.stopIfNotConformable <- function (betahat, sigma, numPrePeriods, numPostPeriods, l_vec) 
{
    betaDim <- c(base::NROW(betahat), base::NCOL(betahat))
    betaL <- base::max(betaDim)
    beta1 <- base::min(betaDim)
    if (beta1 > 1) {
        base::stop(base::sprintf("expected a vector but betahat was %d by %d", betaDim[1], betaDim[2]))
    }
    sigmaR <- base::NROW(sigma)
    sigmaC <- base::NCOL(sigma)
    if (sigmaR != sigmaC) {
        base::stop(base::sprintf("expected a square matrix but sigma was %d by %d", sigmaR, sigmaC))
    }
    if (sigmaR != betaL) {
        base::stop(base::sprintf("betahat (%d by %d) and sigma (%d by %d) were non-conformable", betaDim[1], 
            betaDim[2], sigmaR, sigmaC))
    }
    numPeriods <- numPrePeriods + numPostPeriods
    if (numPeriods != betaL) {
        base::stop(base::sprintf("betahat (%d by %d) and pre + post periods (%d + %d) were non-conformable", 
            betaDim[1], betaDim[2], numPrePeriods, numPostPeriods))
    }
    if (base::length(l_vec) != numPostPeriods) {
        base::stop(base::sprintf("l_vec (length %d) and post periods (%d) were non-conformable", base::length(l_vec), 
            numPostPeriods))
    }
}

hd_.test_delta_lp_fn <- function (y_T, X_T, sigma) 
{
    dimDelta = base::dim(X_T)[2]
    sdVec = base::sqrt(base::diag(sigma))
    f = base::c(1, base::rep(0, dimDelta))
    C = -base::cbind(sdVec, X_T)
    b = -y_T
    linprog = lpSolveAPI::make.lp(nrow = 0, ncol = base::length(f))
    lpSolveAPI::set.objfn(linprog, f)
    for (r in 1:base::dim(C)[1]) {
        lpSolveAPI::add.constraint(linprog, xt = base::c(C[r, ]), type = "<=", rhs = b[r])
    }
    lpSolveAPI::set.bounds(linprog, lower = base::rep(-Inf, base::length(f)), columns = 1:base::length(f))
    lpSolveAPI::lp.control(linprog, sense = "min", simplextype = "dual", pivoting = "dantzig", verbose = "neutral")
    error_flag = lpSolveAPI::solve.lpExtPtr(linprog)
    eta = lpSolveAPI::get.objective(linprog)
    primalSoln = lpSolveAPI::get.primal.solution(linprog)
    delta = primalSoln[(base::length(primalSoln) - dimDelta + 1):base::length(primalSoln)]
    dual = -lpSolveAPI::get.sensitivity.rhs(linprog)$duals[1:base::dim(C)[1]]
    results = base::list(eta_star = eta, delta_star = delta, lambda = dual, error_flag = error_flag)
    base::return(results)
}

hd_.test_delta_lp_fn_wrapper <- function (theta, y_T, X_T, sigma, alpha, hybrid_flag, hybrid_list, rowsForARP = NULL) 
{
    results = hd_.lp_conditional_test_fn(theta = theta, y_T = y_T, X_T = X_T, sigma = sigma, alpha = alpha, 
        hybrid_flag = hybrid_flag, hybrid_list = hybrid_list, rowsForARP = rowsForARP)
    base::return(results$reject)
}

hd_.testInIdentifiedSet <- function (y, sigma, A, d, Abar_additional = NULL, dbar_additional = NULL, alpha) 
{
    sigmaTilde <- base::as.vector(base::sqrt(base::diag(A %*% sigma %*% base::t(A))))
    Atilde <- base::solve(base::diag(sigmaTilde)) %*% A
    dtilde <- base::solve(base::diag(sigmaTilde)) %*% d
    normalizedMoments <- Atilde %*% y - dtilde
    maxLocation <- base::which.max(normalizedMoments)
    maxMoment <- normalizedMoments[maxLocation]
    T_B <- hd_.selectionMat(maxLocation, size = base::NROW(Atilde), select = "rows")
    iota <- base::matrix(1, nrow = base::NROW(Atilde), ncol = 1)
    gamma <- base::t(T_B %*% Atilde)
    Abar <- Atilde - iota %*% T_B %*% Atilde
    dbar <- (base::diag(base::NROW(dtilde)) - iota %*% T_B) %*% dtilde
    if (!base::is.null(Abar_additional)) {
        Abar <- base::rbind(Abar, Abar_additional)
        dbar <- base::c(dbar, dbar_additional)
    }
    sigmabar <- base::sqrt(base::t(gamma) %*% sigma %*% gamma)
    c <- sigma %*% gamma/base::as.numeric(base::t(gamma) %*% sigma %*% gamma)
    z <- (base::diag(base::NROW(y)) - c %*% base::t(gamma)) %*% y
    VLoVUpVec <- hd_.VLoVUpFN(eta = gamma, Sigma = sigma, A = Abar, b = dbar, z = z)
    criticalVal <- base::max(0, hd_.norminvp_generalized(p = 1 - alpha, l = VLoVUpVec[1], u = VLoVUpVec[2], 
        mu = T_B %*% dtilde, sd = sigmabar))
    reject <- (maxMoment + T_B %*% dtilde > criticalVal)
    base::return(reject)
}

hd_.testInIdentifiedSet_FLCI_Hybrid <- function (y, sigma, A, d, alpha, hybrid_list) 
{
    A_firststage <- base::rbind(hybrid_list$flci_l, -hybrid_list$flci_l)
    d_firststage <- base::c(hybrid_list$flci_halflength, hybrid_list$flci_halflength)
    if (base::max(A_firststage %*% y - d_firststage) > 0) {
        reject <- TRUE
    }
    else {
        alphatilde <- (alpha - hybrid_list$hybrid_kappa)/(1 - hybrid_list$hybrid_kappa)
        reject <- hd_.testInIdentifiedSet(y = y, sigma = sigma, A = A, d = d, Abar_additional = A_firststage, 
            dbar_additional = d_firststage, alpha = alphatilde)
    }
    base::return(reject)
}

hd_.testInIdentifiedSet_LF_Hybrid <- function (y, sigma, A, d, alpha, hybrid_list) 
{
    sigmaTilde <- base::as.vector(base::sqrt(base::diag(A %*% sigma %*% base::t(A))))
    Atilde <- base::solve(base::diag(sigmaTilde)) %*% A
    dtilde <- base::solve(base::diag(sigmaTilde)) %*% d
    normalizedMoments <- Atilde %*% y - dtilde
