}

hd_.testOverThetaGrid <- function (betahat, sigma, A, d, thetaGrid, numPrePeriods, alpha, testFn = hd_.testInIdentifiedSet, ...) 
{
    testTauInSetFn <- function(theta) {
        reject <- testFn(y = betahat - hd_basisVector(index = numPrePeriods + 1, size = base::length(betahat)) * 
            theta, sigma = sigma, A = A, d = d, alpha = alpha, ...)
        inSet <- !reject
        base::return(inSet)
    }
    testResultsGrid <- purrr::map_dbl(.x = thetaGrid, .f = testTauInSetFn)
    testValsGrid <- thetaGrid
    resultsGrid <- base::cbind(testValsGrid, testResultsGrid)
    base::return(resultsGrid)
}

hd_.vlo_vup_dual_fn <- function (eta, s_T, gamma_tilde, sigma, W_T) 
{
    tol_c = 1e-06
    tol_equality = 1e-06
    sigma_B = base::sqrt(base::t(gamma_tilde) %*% sigma %*% gamma_tilde)
    low_initial = base::min(-100, eta - 20 * sigma_B)
    high_initial = base::max(100, eta + 20 * sigma_B)
    maxiters = 10000
    switchiters = 10
    checksol = hd_.check_if_solution_helper(eta, tol_equality, s_T, gamma_tilde, sigma, W_T)$honestsolution
    if (base::is.na(checksol) || !checksol) {
        base::return(base::list(vlo = eta, vup = Inf))
    }
    if ((linprog = hd_.check_if_solution_helper(high_initial, tol_equality, s_T, gamma_tilde, sigma, W_T))$honestsolution) {
        vup = Inf
    }
    else {
        dif = 0
        iters = 1
        b = base::c(base::t(gamma_tilde) %*% sigma %*% gamma_tilde)^(-1) * (sigma %*% gamma_tilde)
        mid = (hd_.roundeps(linprog$solution %*% s_T)/(1 - linprog$solution %*% b))[1]
        while (!(linprog = hd_.check_if_solution_helper(mid, tol_equality, s_T, gamma_tilde, sigma, W_T))$honestsolution && 
            (iters < maxiters)) {
            iters = iters + 1
            if (iters >= switchiters) {
                dif = tol_c + 1
                break
            }
            mid = (hd_.roundeps(linprog$solution %*% s_T)/(1 - linprog$solution %*% b))[1]
        }
        low = eta
        high = mid
        while (dif > tol_c & iters < maxiters) {
            iters = iters + 1
            mid = (high + low)/2
            if (hd_.check_if_solution_helper(mid, tol_equality, s_T, gamma_tilde, sigma, W_T)$honestsolution) {
                low = mid
            }
            else {
                high = mid
            }
            dif = high - low
        }
        if (iters == maxiters) {
        }
        vup = mid
    }
    if ((linprog = hd_.check_if_solution_helper(low_initial, tol_equality, s_T, gamma_tilde, sigma, W_T))$honestsolution) {
        vlo = -Inf
    }
    else {
        dif = 0
        iters = 1
        b = base::c(base::t(gamma_tilde) %*% sigma %*% gamma_tilde)^(-1) * (sigma %*% gamma_tilde)
        mid = (hd_.roundeps(linprog$solution %*% s_T)/(1 - linprog$solution %*% b))[1]
        while (!(linprog = hd_.check_if_solution_helper(mid, tol_equality, s_T, gamma_tilde, sigma, W_T))$honestsolution && 
            (iters < maxiters)) {
            iters = iters + 1
            if (iters >= switchiters) {
                dif = tol_c + 1
                break
            }
            mid = (hd_.roundeps(linprog$solution %*% s_T)/(1 - linprog$solution %*% b))[1]
        }
        low = mid
        high = eta
        while (dif > tol_c & iters < maxiters) {
            mid = (low + high)/2
            iters = iters + 1
            if (hd_.check_if_solution_helper(mid, tol_equality, s_T, gamma_tilde, sigma, W_T)$honestsolution) {
                high = mid
            }
            else {
                low = mid
            }
            dif = high - low
        }
        if (iters == maxiters) {
        }
        vlo = mid
    }
    base::return(base::list(vlo = vlo, vup = vup))
}

hd_.VLoVUpFN <- function (eta, Sigma, A, b, z) 
{
    c = hd_.LeeCFN(eta, Sigma)
    objective <- (b - A %*% z)/(A %*% c)
    ACNegativeIndex <- base::which((A %*% c) < 0)
    ACPositiveIndex <- base::which((A %*% c) > 0)
    if (base::length(ACNegativeIndex) == 0) {
        VLo <- -Inf
    }
    else {
        VLo <- base::max(objective[ACNegativeIndex])
    }
    if (base::length(ACPositiveIndex) == 0) {
        VUp <- Inf
    }
    else {
        VUp <- base::min(objective[ACPositiveIndex])
    }
    base::return(base::c(VLo, VUp))
}

hd_.warnIfNotSymmPSD <- function (sigma) 
{
    if (!base::isSymmetric(sigma, check.attributes = FALSE)) {
        base::warning(base::sprintf("matrix sigma not exactly symmetric (largest asymmetry was %g)", 
            base::max(base::abs(sigma - t(sigma)))))
    }
    lambda <- base::eigen(sigma, TRUE, only.values = TRUE)$values
    if (base::any(lambda < 0)) {
        base::warning(base::sprintf("matrix sigma not numerically positive semi-definite (smallest eigenvalue was %g)", 
            base::min(lambda)))
    }
}

hd_basisVector <- function (index = 1, size = 1) 
{
    v <- base::matrix(0, nrow = size, ncol = 1)
    v[index] = 1
    base::return(v)
}

hd_computeConditionalCS_DeltaRM <- function (betahat, sigma, numPrePeriods, numPostPeriods, l_vec = .basisVector(index = 1, size = numPostPeriods), 
    Mbar = 0, alpha = 0.05, hybrid_flag = "LF", hybrid_kappa = alpha/10, returnLength = FALSE, postPeriodMomentsOnly = TRUE, 
    gridPoints = 10^3, grid.ub = NA, grid.lb = NA, seed = 0) 
{
    min_s = -(numPrePeriods - 1)
    s_indices = min_s:0
    sdTheta <- base::c(base::sqrt(base::t(l_vec) %*% sigma[(numPrePeriods + 1):(numPrePeriods + numPostPeriods), 
        (numPrePeriods + 1):(numPrePeriods + numPostPeriods)] %*% l_vec))
    if (base::is.na(grid.ub)) {
        grid.ub = 20 * sdTheta
    }
    if (base::is.na(grid.lb)) {
        grid.lb = -20 * sdTheta
    }
    CIs_RM_plus_allS = base::matrix(0, nrow = gridPoints, ncol = base::length(s_indices))
    CIs_RM_minus_allS = base::matrix(0, nrow = gridPoints, ncol = base::length(s_indices))
    for (s_i in 1:base::length(s_indices)) {
        CI_s_plus = hd_.computeConditionalCS_DeltaRM_fixedS(s = s_indices[s_i], max_positive = TRUE, Mbar = Mbar, 
            betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods, 
            l_vec = l_vec, alpha = alpha, hybrid_flag = hybrid_flag, hybrid_kappa = hybrid_kappa, postPeriodMomentsOnly = postPeriodMomentsOnly, 
            gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
        CIs_RM_plus_allS[, s_i] = CI_s_plus$accept
        CI_s_minus = hd_.computeConditionalCS_DeltaRM_fixedS(s = s_indices[s_i], max_positive = FALSE, Mbar = Mbar, 
            betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods, 
            l_vec = l_vec, alpha = alpha, hybrid_flag = hybrid_flag, hybrid_kappa = hybrid_kappa, postPeriodMomentsOnly = postPeriodMomentsOnly, 
            gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
        CIs_RM_minus_allS[, s_i] = CI_s_minus$accept
    }
    CIs_RM_plus_maxS = base::apply(CIs_RM_plus_allS, MARGIN = 1, FUN = base::max)
    CIs_RM_minus_maxS = base::apply(CIs_RM_minus_allS, MARGIN = 1, FUN = base::max)
    CI_RM = tibble::tibble(grid = base::seq(grid.lb, grid.ub, length.out = gridPoints), accept = base::pmax(CIs_RM_plus_maxS, 
        CIs_RM_minus_maxS))
    if (returnLength) {
        gridLength <- 0.5 * (base::c(0, base::diff(CI_RM$grid)) + base::c(base::diff(CI_RM$grid), 0))
        base::return(base::sum(CI_RM$accept * gridLength))
    }
    else {
        base::return(CI_RM)
    }
}

