        CIs_SDRM_minus_maxS))
    if (returnLength == TRUE) {
        gridLength <- 0.5 * (base::c(0, base::diff(CI_SDRM$grid)) + base::c(base::diff(CI_SDRM$grid), 
            0))
        base::return(base::sum(CI_SDRM$accept * gridLength))
    }
    else {
        base::return(CI_SDRM)
    }
}

hd_computeConditionalCS_DeltaSDRMB <- function (betahat, sigma, numPrePeriods, numPostPeriods, l_vec = .basisVector(index = 1, size = numPostPeriods), 
    Mbar = 0, alpha = 0.05, hybrid_flag = "LF", hybrid_kappa = alpha/10, returnLength = FALSE, postPeriodMomentsOnly = TRUE, 
    biasDirection = "positive", gridPoints = 10^3, grid.ub = NA, grid.lb = NA, seed = 0) 
{
    if (numPrePeriods == 1) {
        base::stop("Error: not enough pre-periods (Delta^{SDRM} as base choice)! Plese see documentation.")
    }
    min_s = -(numPrePeriods - 2)
    s_indices = min_s:0
    sdTheta <- base::c(base::sqrt(base::t(l_vec) %*% sigma[(numPrePeriods + 1):(numPrePeriods + numPostPeriods), 
        (numPrePeriods + 1):(numPrePeriods + numPostPeriods)] %*% l_vec))
    if (base::is.na(grid.ub)) {
        grid.ub = 20 * sdTheta
    }
    if (base::is.na(grid.lb)) {
        grid.lb = -20 * sdTheta
    }
    CIs_SDRMB_plus_allS = base::matrix(0, nrow = gridPoints, ncol = base::length(s_indices))
    CIs_SDRMB_minus_allS = base::matrix(0, nrow = gridPoints, ncol = base::length(s_indices))
    for (s_i in 1:base::length(s_indices)) {
        CI_s_plus = hd_.computeConditionalCS_DeltaSDRMB_fixedS(s = s_indices[s_i], max_positive = TRUE, 
            Mbar = Mbar, betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods, 
            l_vec = l_vec, alpha = alpha, hybrid_flag = hybrid_flag, hybrid_kappa = hybrid_kappa, postPeriodMomentsOnly = postPeriodMomentsOnly, 
            biasDirection = biasDirection, gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, 
            seed = seed)
        CIs_SDRMB_plus_allS[, s_i] = CI_s_plus$accept
        CI_s_minus = hd_.computeConditionalCS_DeltaSDRMB_fixedS(s = s_indices[s_i], max_positive = FALSE, 
            Mbar = Mbar, betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, numPostPeriods = numPostPeriods, 
            l_vec = l_vec, alpha = alpha, hybrid_flag = hybrid_flag, hybrid_kappa = hybrid_kappa, postPeriodMomentsOnly = postPeriodMomentsOnly, 
            biasDirection = biasDirection, gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, 
            seed = seed)
        CIs_SDRMB_minus_allS[, s_i] = CI_s_minus$accept
    }
    CIs_SDRMB_plus_maxS = base::apply(CIs_SDRMB_plus_allS, MARGIN = 1, FUN = base::max)
    CIs_SDRMB_minus_maxS = base::apply(CIs_SDRMB_minus_allS, MARGIN = 1, FUN = base::max)
    CI_SDRMB = tibble::tibble(grid = base::seq(grid.lb, grid.ub, length.out = gridPoints), accept = base::pmax(CIs_SDRMB_plus_maxS, 
        CIs_SDRMB_minus_maxS))
    if (returnLength == TRUE) {
        gridLength <- 0.5 * (base::c(0, base::diff(CI_SDRMB$grid)) + base::c(base::diff(CI_SDRMB$grid), 
            0))
        base::return(base::sum(CI_SDRMB$accept * gridLength))
    }
    else {
        base::return(CI_SDRMB)
    }
}

