hd_constructOriginalCS <- function (betahat, sigma, numPrePeriods, numPostPeriods, l_vec = .basisVector(index = 1, size = numPostPeriods), 
    alpha = 0.05) 
{
    hd_.stopIfNotConformable(betahat, sigma, numPrePeriods, numPostPeriods, l_vec)
    hd_.warnIfNotSymmPSD(sigma)
    stdError = base::sqrt(base::t(l_vec) %*% sigma[(numPrePeriods + 1):(numPrePeriods + numPostPeriods), 
        (numPrePeriods + 1):(numPrePeriods + numPostPeriods)] %*% l_vec)
    lb = base::t(l_vec) %*% betahat[(numPrePeriods + 1):(numPrePeriods + numPostPeriods)] - stats::qnorm(1 - 
        alpha/2) * stdError
    ub = base::t(l_vec) %*% betahat[(numPrePeriods + 1):(numPrePeriods + numPostPeriods)] + stats::qnorm(1 - 
        alpha/2) * stdError
    base::return(tibble::tibble(lb = lb, ub = ub, method = "Original", Delta = NA))
}

hd_createSensitivityResults_relativeMagnitudes <- function (betahat, sigma, numPrePeriods, numPostPeriods, bound = "deviation from parallel trends", method = "C-LF", 
    Mbarvec = NULL, l_vec = .basisVector(index = 1, size = numPostPeriods), monotonicityDirection = NULL, 
    biasDirection = NULL, alpha = 0.05, gridPoints = 10^3, grid.ub = NA, grid.lb = NA, parallel = FALSE, 
    seed = 0) 
{
    hd_.CustomErrorHandling({
        hd_.stopIfNotConformable(betahat, sigma, numPrePeriods, numPostPeriods, l_vec)
        hd_.warnIfNotSymmPSD(sigma)
        m <- NULL
        if (base::is.null(Mbarvec)) {
            Mbarvec = base::seq(from = 0, to = 2, length.out = 10)
        }
        if (bound != "deviation from parallel trends" & bound != "deviation from linear trend") {
            base::stop("bound must equal either 'deviation from parallel trends' or 'deviation from linear trend'.")
        }
        if (!base::is.null(monotonicityDirection) & !base::is.null(biasDirection)) {
            base::stop("Please select either a shape restriction or sign restriction (not both).")
        }
        if (method == "C-LF") {
            hybrid_flag = "LF"
            method_named = "C-LF"
        }
        else if (method == "Conditional") {
            hybrid_flag = "ARP"
            method_named = "Conditional"
        }
        else {
            base::stop("method must be either NULL, Conditional or C-LF.")
        }
        if (bound == "deviation from parallel trends") {
            if (base::is.null(monotonicityDirection) & base::is.null(biasDirection)) {
                Delta = "DeltaRM"
                if (parallel) {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %dopar% 
                    {
                      temp = hd_computeConditionalCS_DeltaRM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                        numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                        hybrid_flag = hybrid_flag, gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, 
                        seed = seed)
                      tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                        1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                    }
                }
                else {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %do% {
                    temp = hd_computeConditionalCS_DeltaRM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                      numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                      hybrid_flag = hybrid_flag, gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, 
                      seed = seed)
                    tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                      1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                  }
                }
            }
            else if (!base::is.null(monotonicityDirection)) {
                if (monotonicityDirection == "increasing") {
                  Delta = "DeltaRMI"
                }
                else if (monotonicityDirection == "decreasing") {
                  Delta = "DeltaRMD"
                }
                else {
                  base::stop("monotonicityDirection must equal either increasing or decreasing.")
                }
                if (parallel) {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %dopar% 
                    {
                      temp = hd_computeConditionalCS_DeltaRMM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                        numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                        monotonicityDirection = monotonicityDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                        grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                      tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                        1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                    }
                }
                else {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %do% {
                    temp = hd_computeConditionalCS_DeltaRMM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                      numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                      monotonicityDirection = monotonicityDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                      grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                    tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                      1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                  }
                }
            }
            else {
                if (biasDirection == "positive") {
                  Delta = "DeltaRMPB"
                }
                else if (biasDirection == "negative") {
                  Delta = "DeltaRMNB"
                }
                else {
                  base::stop("monotonicityDirection must equal either positive or negative.")
                }
                if (parallel) {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %dopar% 
                    {
                      temp = hd_computeConditionalCS_DeltaRMB(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                        numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                        biasDirection = biasDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                        grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                      tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                        1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                    }
                }
                else {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %do% {
                    temp = hd_computeConditionalCS_DeltaRMB(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                      numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                      biasDirection = biasDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                      grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                    tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                      1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                  }
                }
            }
        }
        else {
            if (numPrePeriods == 1) {
                base::stop("Error: not enough pre-periods for 'deviation from linear trend' (Delta^{SDRM} as base choice). Plese see documentation.")
            }
            if (base::is.null(monotonicityDirection) & base::is.null(biasDirection)) {
                Delta = "DeltaSDRM"
                if (parallel) {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %dopar% 
                    {
                      temp = hd_computeConditionalCS_DeltaSDRM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                        numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                        hybrid_flag = hybrid_flag, gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, 
                        seed = seed)
                      tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                        1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                    }
                }
                else {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %do% {
                    temp = hd_computeConditionalCS_DeltaSDRM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                      numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                      hybrid_flag = hybrid_flag, gridPoints = gridPoints, grid.ub = grid.ub, grid.lb = grid.lb, 
                      seed = seed)
                    tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                      1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                  }
                }
            }
            else if (!base::is.null(monotonicityDirection)) {
                if (monotonicityDirection == "increasing") {
                  Delta = "DeltaSDRMI"
                }
                else if (monotonicityDirection == "decreasing") {
                  Delta = "DeltaSDRMD"
                }
                else {
                  base::stop("monotonicityDirection must equal either increasing or decreasing.")
                }
                if (parallel) {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %dopar% 
                    {
                      temp = hd_computeConditionalCS_DeltaSDRMM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                        numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                        monotonicityDirection = monotonicityDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                        grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                      tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                        1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                    }
                }
                else {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %do% {
                    temp = hd_computeConditionalCS_DeltaSDRMM(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                      numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                      monotonicityDirection = monotonicityDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                      grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                    tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                      1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                  }
                }
            }
            else {
                if (biasDirection == "positive") {
                  Delta = "DeltaSDRMPB"
                }
                else if (biasDirection == "negative") {
                  Delta = "DeltaSDRMNB"
                }
                else {
                  base::stop("monotonicityDirection must equal either positive or negative.")
                }
                if (parallel) {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %dopar% 
                    {
                      temp = hd_computeConditionalCS_DeltaSDRMB(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                        numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
                        biasDirection = biasDirection, hybrid_flag = hybrid_flag, gridPoints = gridPoints, 
                        grid.ub = grid.ub, grid.lb = grid.lb, seed = seed)
                      tibble::tibble(lb = base::min(temp$grid[temp$accept == 1]), ub = base::max(temp$grid[temp$accept == 
                        1]), method = method_named, Delta = Delta, Mbar = Mbarvec[m])
                    }
                }
                else {
                  Results = foreach::foreach(m = 1:base::length(Mbarvec), .combine = "rbind") %do% {
                    temp = hd_computeConditionalCS_DeltaSDRMB(betahat = betahat, sigma = sigma, numPrePeriods = numPrePeriods, 
                      numPostPeriods = numPostPeriods, l_vec = l_vec, alpha = alpha, Mbar = Mbarvec[m], 
